# /app is read-only, so a game that saves next to itself (relative paths) would fail. The media is found through /app/game, and the working
# directory is a writable folder of the game: files that the game writes land in ~/.var/app/<app-id>/data, files it opens are looked up
# there first and then in /app/game when it uses absolute paths (or copy them: see below).
data="${XDG_DATA_HOME:-$HOME/.local/share}"
mkdir -p "$data"
# Make the shipped files visible in the working directory without copying them.
for f in /app/game/*; do
	n="$(basename "$f")"
	[ -e "$data/$n" ] || ln -s "$f" "$data/$n"
done
cd "$data" || exit 1
exec /app/game/mygame "$@"
